const campo=document.getElementById("q"),temas=[...document.querySelectorAll(".tema")],vacio=document.getElementById("busqueda-vacia"),estado=document.getElementById("busqueda-estado");function filtrar(){const e=campo.value.trim().toLocaleLowerCase("es");let t=0;for(const o of temas){const a=""===e||o.textContent.toLocaleLowerCase("es").includes(e);o.hidden=!a,a&&(t+=1)}vacio.hidden=0!==t,estado.textContent=""===e?"":1===t?"1 tema":`${t} temas`}campo.addEventListener("input",filtrar);